def nth_root(n: int, x: int) -> int:
    def power_cmp(m: int) -> int:
        p = 1
        for _ in range(n):
            p *= m
            if p > x:
                return 1
        return 0 if p == x else -1

    lo, hi = 1, x
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        c = power_cmp(mid)
        if c == 0:
            return mid
        if c < 0:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
